-- StarterGui.bonds.TextButton.LocalScript
local function C_3()
local script = G2L["3"];
	script.Parent.Activated:Connect(function()
		local player = game.Players.LocalPlayer
		local char = player.Character
		local backpack = player.Backpack

		local function getf3x()
			for _, v in ipairs(backpack:GetChildren()) do
				if v:FindFirstChild("SyncAPI") then
					return v
				end
			end
			for _, v in ipairs(char:GetChildren()) do
				if v:FindFirstChild("SyncAPI") then
					return v
				end
			end

			return nil
		end

		-- get all info

		local f3x = getf3x()
		if not f3x then
			warn("you dont have f3x skid")
		end
		local syncapi = f3x.SyncAPI
		local serverendpoint = syncapi.ServerEndpoint

		local function syncmaterial(part,mate)
			local args = {
				[1] = "SyncMaterial",
				[2] = {
					[1] = {
						["Part"] = part,
						["Material"] = mate
					}
				}
			}
			serverendpoint:InvokeServer(unpack(args))
		end

		local function color(part, color)
			local args = {
				[1] = "SyncColor",
				[2] = {
					[1] = {
						["Part"] = part,
						["Color"] = color --[[Color3]],
						["UnionColoring"] = false
					}
				}
			}
			serverendpoint:InvokeServer(unpack(args))
		end

		local function createdecal(part, side)
			local args = {
				[1] = "CreateTextures",
				[2] = {
					[1] = {
						["Part"] = part,
						["Face"] = side,
						["TextureType"] = "Decal"
					}
				}
			}
			serverendpoint:InvokeServer(unpack(args))
		end
		local function setdecal(part, asset, side)
			local args = {
				[1] = "SyncTexture",
				[2] = {
					[1] = {
						["Part"] = part,
						["Face"] = side,
						["TextureType"] = "Decal",
						["Texture"] = "rbxassetid://".. asset
					}
				}
			}
			serverendpoint:InvokeServer(unpack(args))
		end

		local function resize(part,size,cf)
			local args = {
				[1] = "SyncResize",
				[2] = {
					[1] = {
						["Part"] = part,
						["CFrame"] = cf,
						["Size"] = size
					}
				}
			}
			serverendpoint:InvokeServer(unpack(args))
		end

		local function setanchor(part, boolean)
			local args = {
				[1] = "SyncAnchor",
				[2] = {
					[1] = {
						["Part"] = part,
						["Anchored"] = boolean
					}
				}
			}
			serverendpoint:InvokeServer(unpack(args))
		end

		local char = player.Character or player.CharacterAdded:Wait()
		local head = char.Head
		local cf = head.CFrame * CFrame.new(0, 20, 0)

		local function rainbonds()
			while task.wait(0.1) do
				spawn(function()
					local bond = serverendpoint:InvokeServer("CreatePart", "Normal", cf, workspace)
					local bondtxture = 123280663984547

					local decal1 =  createdecal(bond, Enum.NormalId.Top) setdecal(bond, bondtxture, Enum.NormalId.Top)
					local decal2 =  createdecal(bond, Enum.NormalId.Bottom) setdecal(bond, bondtxture, Enum.NormalId.Bottom)

					color(bond, Color3.new(0.917647, 0.721569, 0.572549))
					syncmaterial(bond, Enum.Material.Leather)
					resize(bond, Vector3.new(1.96, 0.15, 1), cf)
					setanchor(bond, false)
				end)
			end
		end

		rainbonds()
	end)
end;
task.spawn(C_3);

